explorer=(src/'Explorer.cs').read_text()
lines=[]
for line in explorer.splitlines():
 if '.set_' in line:
  prefix,tail=line.split('.set_',1);name,value=tail.split('(',1);line=prefix+'.'+name+' = '+value.rsplit(');',1)[0]+';'
 lines.append(line)
(out/'Explorer.cs').write_text('\n'.join(lines),encoding='utf-8')
